{"path":"src/java_module.java","content":"// Метод ищет активного пользователя по логину.
// Возвращает Optional, чтобы явно показать, что пользователь может отсутствовать,
// а не возвращать null (это защищает вызывающий код от NullPointerException).
public Optional<User> findActive(String login) {
    // Берём поток из коллекции пользователей и последовательно фильтруем:
    return users.stream()
        // 1) Отбираем пользователя с совпадающим логином.
        // equalsIgnoreCase — чтобы поиск не зависел от регистра (например, "Admin" == "admin").
        .filter(u -> u.getLogin().equalsIgnoreCase(login))
        // 2) Проверяем, что пользователь активен:
        //    - не заблокирован (isBlocked == false);
        //    - срок действия ещё не истёк (expiresAt позже текущего момента времени).
        // Instant.now() — текущий момент в UTC, сравниваем с датой истечения.
        .filter(u -> !u.isBlocked() && u.getExpiresAt().isAfter(Instant.now()))
        // Берём первый подходящий элемент; если подходящих нет — получим пустой Optional.
        .findFirst();
}
"}

{"path":"src/csharp_module.cs","content":"/// <summary>
/// Выполняет асинхронное действие с повторными попытками (retry) при сетевых ошибках.
/// </summary>
/// <param name="action">Действие, которое нужно выполнить. Возвращает результат в виде int.</param>
/// <param name="attempts">Максимальное количество попыток выполнения действия.</param>
/// <returns>Результат успешного выполнения действия.</returns>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Перебираем попытки от 0 до attempts - 1.
    // Индекс i используется для расчёта экспоненциальной задержки между попытками.
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Пытаемся выполнить действие.
            // Если оно завершилось успешно — сразу возвращаем результат.
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        // Перехватываем только сетевые ошибки (HttpRequestException).
        // Условие "when (i < attempts - 1)" гарантирует, что:
        //   1) мы не делаем лишнюю задержку после последней неудачной попытки;
        //   2) если это была последняя попытка, исключение пробрасывается наружу,
        //      и вызывающий код сам решает, как его обработать.
        {
            // Экспоненциальная задержка (exponential backoff):
            // 200 мс * 2^i => 200, 400, 800, 1600 ... мс.
            // Такой подход снижает нагрузку на сервер/сеть при частых сбоях
            // и даёт время на восстановление соединения.
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
    }

    // Эта строка недостижима: либо метод уже вернул результат,
    // либо было выброшено исключение из последней попытки.
    // Оставляем её, чтобы компилятор был уверен, что метод всегда возвращает значение.
    throw new InvalidOperationException("unreachable");
}
"}

{"path":"src/go_module.go","content":"// worker — функция-обработчик, которая работает как отдельный воркер (поток)
// в пуле. Она читает задачи из канала jobs, обрабатывает каждую и отправляет
// результат в канал results.
//
// Параметры:
//   - jobs    — входной канал задач (только чтение). Воркер читает из него
//     по одной задаче за раз, пока канал не будет закрыт.
//   - results — выходной канал результатов (только запись). Сюда воркер
//     кладёт успешно обработанные результаты.
//   - wg      — указатель на sync.WaitGroup, который используется для
//     синхронизации: когда воркер завершит работу, он уменьшает счётчик,
//     что позволяет главному потоку дождаться завершения всех воркеров.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
	// defer гарантирует, что Done() вызовется при выходе из функции,
	// независимо от того, как именно воркер завершился (нормально или с ошибкой).
	// Это уменьшает счётчик WaitGroup на 1.
	defer wg.Done()

	// Цикл range по каналу: он блокируется, пока в канале нет данных,
	// и автоматически завершается, когда канал jobs будет закрыт.
	for j := range jobs {
		// process — основная логика обработки задачи.
		// Возвращает результат и возможную ошибку.
		r, err := process(j)

		// Если произошла ошибка — логируем её и пропускаем задачу,
		// не прерывая работу всего воркера. Так одна «плохая» задача
		// не влияет на обработку остальных.
		if err != nil {
			log.Printf("job %d: %v", j.ID, err)
			continue
		}

		// Отправляем успешный результат в канал results.
		// Операция блокируется, пока потребитель не заберёт значение,
		// что обеспечивает естественное ограничение скорости (backpressure).
		results <- r
	}
}
"}

{"path":"src/typescript_module.ts","content":"/**
 * Создаёт «debounce»-обёртку вокруг переданной функции.
 *
 * Что делает:
 * Возвращает новую функцию, которая откладывает вызов исходной `fn`
 * на `ms` миллисекунд. Если за это время обёртка вызывается снова,
 * предыдущий таймер сбрасывается и отсчёт начинается заново.
 * В итоге `fn` выполнится только один раз — через `ms` после
 * последнего вызова обёртки (пока вызовы не прекратились).
 *
 * Зачем так:
 * - Тип `T extends (...a: any[]) => void` позволяет принять любую
 *   функцию с произвольными аргументами, сохранив при этом её точную
 *   сигнатуру. Благодаря этому TypeScript корректно проверяет типы
 *   аргументов и возвращаемого значения у оригинала.
 * - `Parameters<T>` извлекает кортеж типов аргументов исходной функции,
 *   поэтому обёртка принимает ровно те же параметры, что и `fn`.
 * - Переменная `t` хранит идентификатор текущего таймера. Она объявлена
 *   в замыкании, чтобы состояние (таймер) сохранялось между вызовами
 *   одной и той же обёртки, но было изолировано для разных инстансов.
 * - `clearTimeout(t)` отменяет ещё не сработавший таймер, чтобы каждый
 *   новый вызов «перезапускал» отсчёт — это и есть суть debounce.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Идентификатор активного таймера; `undefined`, пока таймер не создан.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем функцию-обёртку с теми же параметрами, что и исходная.
  return (...args: Parameters<T>) => {
    // Если уже есть незавершённый таймер — отменяем его,
    // чтобы повторный вызов перезапустил отсчёт.
    if (t) clearTimeout(t);

    // Ставим новый таймер: по истечении `ms` вызываем `fn`
    // с последними переданными аргументами.
    t = setTimeout(() => fn(...args), ms);
  };
}
"}

{"path":"src/kotlin_module.kt","content":"/**
 * Безопасная (потокобезопасная) версия функции [MutableMap.getOrPut].
 *
 * @param K — тип ключей в карте.
 * @param V — тип значений в карте.
 * @param key — ключ, по которому ищем значение.
 * @param factory — лямбда, которая создаёт новое значение, если его ещё нет в карте.
 * @return значение из карты: либо уже существующее, либо только что созданное фабрикой.
 */
fun <K, V> MutableMap<K, V>.getOrGetSafe(key: K, factory: () -> V): V =
    // Оборачиваем всю операцию в synchronized(this), чтобы гарантировать атомарность:
    // проверка наличия ключа и запись нового значения выполняются как единый блок,
    // и два потока не смогут одновременно создать и записать разные значения для одного ключа.
    synchronized(this) {
        // this[key] ?: ... — берём значение по ключу; если его нет (null),
        // вызываем factory(), сохраняем результат в карту и возвращаем его.
        this[key] ?: factory().also { this[key] = it }
    }
"}

{"path":"src/rust_module.rs","content":"use std::collections::HashMap;

/// Разбирает строку в формате "ключ1=значение1;ключ2=значение2" в хеш-мапу.
///
/// Формат входной строки: пары «ключ=значение», разделённые точкой с запятой.
/// Пример: `"Name=John;Age=30"` -> `{"name": "John", "age": "30"}`.
///
/// Почему именно так:
/// - Используем итераторы (`split`, `filter_map`, `map`, `collect`), потому что
///   это идиоматичный, производительный и лаконичный способ обработки строк в Rust:
///   нет промежуточных коллекций, всё делается за один проход.
/// - Ключ приводим к нижнему регистру (`to_lowercase`) — чтобы поиск не зависел
///   от регистра (например, "Name" и "name" считались бы одним ключом).
/// - Значение оставляем как есть, только убираем лишние пробелы по краям.
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    s.split(';') // 1. Режем строку на части по разделителю ';'
        .filter_map(|p| p.split_once('=')) // 2. Оставляем только те части, где есть '=';
                                           //    split_once возвращает Option<&(k, v)>:
                                           //    None для частей без '=' (их пропускаем),
                                           //    Some((ключ, значение)) — для корректных пар.
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string())) // 3. Приводим ключ к нижнему
                                                                       //    регистру и обрезаем пробелы,
                                                                       //    значение тоже очищаем от пробелов.
        .collect() // 4. Собираем все пары в HashMap<String, String>.
}
"}
